type HumanOperation struct{ Name, Description string }

func HumanOperations() []HumanOperation {
	return []HumanOperation{{Name: "GetOwnAgentConfiguration", Description: "Read the signed caller's durable Langfuse and OpenSearch references. The response contains opaque secret references, never secret values."}, {Name: "UpdateOwnAgentConfiguration", Description: "Replace the signed caller's Langfuse and OpenSearch references. expected_revision prevents an older agent session from overwriting a newer configuration."}, {Name: "PrepareAgentAssignment", Description: "Validate an agent recipe and prepare stable retry identities without starting a session. Execute the plan with the generated Workbench session and prompt operations; retain the recipe and receipt. This scaffold leaves Copilot context behavior unchanged."}, {Name: "SendEmail", Description: "Email the configured operator. Requires an authenticated agent session. The host automatically attaches Spine provenance and retains a delivery receipt; SMTP acceptance does not prove inbox delivery. Do not blindly retry an unknown outcome."}, {Name: "GetAgentExecutorDefault", Description: "Read the turn executor and model a recipe that names no executor runs on."}, {Name: "SetAgentExecutorDefault", Description: "Switch the turn executor and model every session submitted from now on runs on when its recipe names no executor: the way to move the whole harness to another model provider at once, as when one provider's usage quota runs out. Running sessions keep theirs."}, {Name: "RecordRuling", Description: "Record one operator ruling and the alternatives it rules out. From the next turn of every session, the question gate refuses a question, or an offered alternative, that names an excluded alternative. Returns the rulings in force."}, {Name: "CancelAgentSession", Description: "Ask a session's owner to stop at its next safepoint: at once between turns, or after the running turn is interrupted. Read the session again to see it reach CANCELED."}, {Name: "CheckAgentSessionAdmission", Description: "Report the launch check a recipe would meet now, without admitting it: the host's measured load, free disk and worker cap, the findings, and why admission is held when it is."}, {Name: "GetAgentSession", Description: "Read one session's state by its assignment identifier."}, {Name: "ListInbox", Description: "Report every message in a session's inbox with its state and priority class."}, {Name: "ListAgentSessions", Description: "List every session this harness process holds, with its phase, turns and queue, and the one process they all run in."}, {Name: "MergeAgentSessionPullRequest", Description: "Merge a session's pull request through the repository's merge path (tools/merge-pr.sh when the worktree has one, else gh's squash merge). It waits for the merge path's checks; the report is the path's output. The action is recorded in the session's event log."}, {Name: "ProposeProposal", Description: "Apply a proposed patch to a session's worktree in patch mode, returning a typed rejection when it is not accepted."}, {Name: "ReadyAgentSessionPullRequest", Description: "Mark a session's draft pull request ready for review. The action is recorded in the session's event log."}, {Name: "SendAgentSessionMessage", Description: "Queue one message for an open session; its owner starts the turn at the next safepoint. The turn identifier acknowledges acceptance, not completion. Follow the session's event stream to read the turn."}, {Name: "SubmitAgentSession", Description: "Admit one agent assignment recipe as a session of this host's agent harness: the worktree is created, the session gates are installed and the turn executor is kept open for later messages. The receipt links the session, branch and trace; it does not prove the task succeeded."}, {Name: "StopHarness", Description: "Stop the harness process in order: listeners first, then every open session. Running sessions are closed, not completed."}, {Name: "GetDocument", Description: "Open one saved source document and read its words."}, {Name: "IngestDocument", Description: "Add a source document so people can find and cite it later."}, {Name: "PutEdge", Description: "Connect two ideas and record why they belong together."}, {Name: "GetGraph", Description: "Browse the ideas connected to a starting point."}, {Name: "PutNode", Description: "Add one idea to the shared knowledge map."}, {Name: "Search", Description: "Find saved knowledge that matches a question."}, {Name: "LearnAboutCSF", Description: "Explain the pinned CSF contract and index explicitly selected onboarding sources for retrieval."}, {Name: "CancelSimulation", Description: "Request termination; inspect again to see whether provider cleanup is confirmed."}, {Name: "RecordSimulationEvents", Description: "Record bounded progress from an explicitly registered local simulator worker."}, {Name: "InspectSimulation", Description: "Inspect your simulator's progress, provider status, metrics and artifact location."}, {Name: "ListSimulations", Description: "List recent simulator examples and their actual execution states."}, {Name: "ReadSimulationLogs", Description: "Read bounded local job logs, including retained output after container cleanup."}, {Name: "SubmitSimulation", Description: "Queue a bounded simulator example using the operator's configured execution profile."}, {Name: "RebuildSimulationTrace", Description: "Rebuild a simulator trace from its retained OpenSearch source document."}, {Name: "GetSnapshot", Description: "Show the latest measured work and health report, including whether the external spine controller is connected."}, {Name: "GetWorkbenchTheme", Description: "Read the active Workbench CSS and its host-owned file path. Edit workbench-theme.css at that path, then call ReloadWorkbenchTheme."}, {Name: "ReloadWorkbenchTheme", Description: "Reload the host-owned workbench-theme.css file after editing it. Missing or empty CSS restores the default; invalid UTF-8 or over 65536 bytes preserves the active theme. Browsers refresh within five seconds while visible. Use /ui/?theme=default to bypass broken CSS in one tab. No path or CSS input is accepted."}}
}
